local M = class("TreasureQuestPopView", LikeOO.OOPopBase)

M.m_uiName = "GiftBag/TreasureQuestPop"
M.m_size_type = 2


function M:onEnter()
    self.reward_node = self:findGameObject("reward_node")
    self:setTextByLanKey("common_title_text", "new_str_0360")
    self:setTextByLanKey("task_text", "new_str_1062")
    self:setTextByLanKey("get_reward_text", "new_str_0970")
    self:refreshUI()
end

function M:refreshUI()
    local task_cfg = self.m_model:getTreasureQuestCfg()
    local task_data = self.m_model:getTreasureQuestData()
    self:setTextByLanKey("count_text", task_cfg.name) --任务信息
    local progress_slider = self:findSlider("progress_slider") --进度条
    local value, max_value = task_data.value, task_cfg.target_value
    progress_slider.value = value/max_value
    self:setTextByLanKey("progress_num", value.."/"..max_value)
    local reward = {}
    UIUtil.destroyAllChild(self.reward_node.transform)
    for i,v in pairs(task_cfg.reward) do
        local itemNode = GameUtil:createItemElement(v, true, true)
        itemNode.transform:SetParent(self.reward_node.transform, false)
    end
end


return M